uart-stat.src:
: uart-stat ( mask -- f ) \ is bit in UART status register on?
    h# 2000 io@ and 0<>
;

w+!.src:
: w+!   ( u a -- ) \ like +! but for 16-bit a
    tuck uw@ + swap w!
;

source!.src:
: source! ( addr u -- ) \ set the source
    sourceC 2!
;

-throw.src:
: -throw ( a b -- ) \ if a is nonzero, throw -b
    negate and throw
;

isvoid.src:
: isvoid ( caddr u -- ) \ any char remains, throw -13
    nip 0<> d# 13 -throw
;

tnegate.src:
: tnegate                           ( t . . -- -t . . )
    >r  2dup or dup if drop  dnegate 1  then
    r> +  negate ;

sgn.src:
: sgn ( u1 n1 -- n2 ) \ n2 is u1 with the sign of n1
    0< if negate then
;

